-- --------------------------------------------------------------------------------------------------------------
-- 1. 14 missions (catalog 1 to 14), every one a draft
insert into public.action_missions
  (id, campaign_id, title, description, domain, difficulty, base_points, proof_required, verification_mode,
   skills, capacity, status, starts_at, ends_at, kind, discovery_category)
select v.id, null, v.title, v.description, v.domain, v.difficulty, v.base_points, true, v.verification_mode,
       v.skills, null, 'draft', null, null, 'civic', v.discovery_category
  from (values
    ('237b2be1-b651-5f68-9af3-f26076bb823b'::uuid, -- drawdown-deploy-alternative-insulation-materials
     'Compare insulation labels at a hardware store',
     'Visit a hardware store or its website and compare the labels and product sheets for a few kinds of insulation, such as cellulose, mineral wool, fiberglass and foam board. Note what each is made of and anything the maker says about recycled content, then turn your notes into a simple comparison chart. Post a photo of your chart.',
     'research', 'explore', 2, 100, 'review', array['research','data-analysis']::text[]),
    ('c44d0a0d-1c7f-5396-a071-80149e36c664'::uuid, -- drawdown-deploy-alternative-refrigerants
     'Find out which refrigerant your fridge uses',
     'Look for the rating label on your fridge or freezer, often inside the door or on an inner wall, which names the refrigerant it uses. Look up that refrigerant from an official or manufacturer source and write a sentence or two on what you learned. Post a photo of the label next to your note.',
     'education', 'explore', 1, 100, 'review', array['research','observation']::text[]),
    ('169089fe-4e2c-54b5-a91f-11fcde81d44d'::uuid, -- drawdown-improve-refrigerant-management
     'Share how to safely get rid of an old fridge',
     'Find out how your city, county or utility handles old fridges, freezers and air conditioners, including any pickup or drop-off service that removes the refrigerant properly. Turn the official steps into a short, friendly post or flyer for your building or neighborhood group, with links to the official pages. Post a link or photo of what you shared.',
     'education', 'create', 1, 100, 'review', array['research','writing']::text[]),
    ('7bf1aab9-7278-547d-810b-df442bb1eb04'::uuid, -- drawdown-deploy-building-automation-systems
     'Ask a public building how it controls its energy use',
     'Pick a public building you use, such as a library, school or community center, and send a short, polite question in your own words to its facilities office or the agency that runs it: does the building use automatic controls to schedule heating, cooling and lights, and who looks after them? Use the official contact form, email or a public comment period. Post your question and any reply, with names and contact details removed.',
     'advocacy', 'explore', 2, 100, 'review', array['research','writing']::text[]),
    ('72c015b4-1c69-50d5-adee-2264d5fd2a53'::uuid, -- drawdown-improve-district-heating-buildings
     'Find out if your town has shared heating pipes',
     'District heating means one central plant pipes heat to many buildings. Use public sources such as your city, university, hospital or utility websites to find out whether there is a district heating network near you, or where the nearest one is. Make a short explainer with a simple map and the sources you used, and post it.',
     'research', 'explore', 2, 100, 'review', array['research','mapping']::text[]),
    ('bcf5b9c7-0423-5586-8fba-06b57be0ff19'::uuid, -- drawdown-use-heat-pumps
     'Interview someone who heats with a heat pump',
     'Find a friend, relative or neighbor who already heats their home with a heat pump and ask a few simple questions: how it handles cold and hot days, what surprised them, and what they wish they had known. Get their permission before recording or quoting them, and leave out their address and other personal details. Post a short written or audio summary so neighbors weighing their own heating choices can hear from someone nearby.',
     'research', 'explore', 1, 100, 'review', array['interviewing','writing']::text[]),
    ('02f26a02-9e16-50ff-aa3a-ff108aa9756c'::uuid, -- drawdown-use-smart-programmable-thermostats
     'Help a neighbor set up their thermostat schedule',
     'If a family member or neighbor has a programmable or smart thermostat but has never set a schedule and would like help, sit down with them and read the manual together. Set times that keep the home comfortable when people are in and ease off when they are out or asleep, with the resident deciding every setting and doing any app sign-in themselves. Post a short note on what you set up together.',
     'mutual_aid', 'help', 1, 100, 'review', array['mutual_aid','teaching']::text[]),
    ('8d7a5b07-2074-56b3-8355-47f79877d568'::uuid, -- drawdown-improve-windows-glass
     'Map the drafty windows in your home',
     'On a cool or windy day, move slowly around each window you can reach from the floor and hold a strip of tissue paper near the edges; if it flutters, you have found a draft. Mark each drafty spot on a simple sketch of your home, and if you rent, you can share the list politely with your landlord or building manager. Post a photo of your sketch.',
     'research', 'explore', 1, 100, 'review', array['observation']::text[]),
    ('0cab1dcb-56e2-501d-87e4-bee9130bf456'::uuid, -- drawdown-deploy-agrivoltaics
     'Ask farmers at a market about solar on farmland',
     'Visit a farmers market and, when stalls are quiet, ask a few farmers what they think about putting solar panels on farmland, including setups where crops grow or animals graze under the panels. If no market is open near you, ask a farm or two the same question through their public contact pages. Take notes, and only record or photograph people who say yes. Post a short summary of what you heard, without names unless people agreed to be named.',
     'research', 'explore', 2, 100, 'review', array['interviewing','writing']::text[]),
    ('14a40713-7381-5a28-8506-03b4df42f043'::uuid, -- drawdown-deploy-distributed-solar-pv
     'Find solar options for renters in your area',
     'Many people who rent or live in apartments can''t put panels on their own roof. Look up official information from your state, regional or national energy office, or your utility, about community solar or other programs that let renters use solar power, and write a plain-language summary with links. Share it with a renters'' group, building or neighborhood group and post a link or photo.',
     'research', 'explore', 2, 100, 'review', array['research','writing','outreach']::text[]),
    ('ba11cd9a-9260-548e-b5ef-93ff0f0445db'::uuid, -- drawdown-deploy-led-lighting
     'Take a lighting inventory of your home',
     'Walk through your home and, for each lamp or light fixture you can see clearly from the floor, note whether it holds an LED, compact fluorescent, halogen or old-style bulb, using the packaging or the printing on the bulb where you can. Make a simple tally and share it with your household so you know where switching could help when bulbs burn out. Post a photo of your tally.',
     'research', 'explore', 1, 100, 'review', array['observation','data-analysis']::text[]),
    ('82ce9fb9-9081-5523-a130-c37f3dc6900a'::uuid, -- drawdown-deploy-offshore-wind-turbines
     'Write a short song about wind power at sea',
     'Write and record a short song, rap or spoken-word piece about wind turbines out at sea sending power to homes on shore, and about the people who build and look after them. A phone recording is fine; give it a title and credit everyone who helped. Post the recording and the lyrics.',
     'music', 'create', 1, 100, 'review', array['songwriting','music']::text[]),
    ('400c34d6-e2d4-5977-84a6-21373c17f230'::uuid, -- drawdown-deploy-onshore-wind-turbines
     'Comment on a wind project in a public process',
     'Look through official sources, such as your state or regional energy siting board, county planning office or national permitting portal, for a wind project that is open for public comment. Read the summary, then write a short, respectful comment in your own words about what matters to your community, and submit it, or save it as a draft for a project whose comment period opens soon. Post a link or screenshot of your comment with personal details removed.',
     'advocacy', 'create', 3, 150, 'review', array['policy-analysis','writing']::text[]),
    ('9890ab86-5e07-5dfc-ab69-40874c388b01'::uuid, -- drawdown-deploy-utility-scale-solar-pv
     'Find the nearest large solar farm on a public map',
     'Use a free public map of power plants from your national energy agency or a similar official source to find the large solar farms closest to you. Make a short post with a screenshot, each site''s name and owner if listed, and one thing you learned about it. If there''s a public hearing coming up about a new solar project near you, include the date and how to take part.',
     'research', 'explore', 2, 100, 'review', array['research','mapping']::text[])
  ) as v(id, title, description, domain, discovery_category, difficulty, base_points, verification_mode, skills)
on conflict (id) do nothing;

